//msg.payload = Buffer.from([0xdd, 0xa5, 0x03, 0x00, 0xff, 0xfd , 0x77])

// JKBMS Dump all registers:
// 4E 57 00 13 00 00 00 00 06 03 00 00 00 00 00 00 68 00 00 01 29
msg = {
    payload: Buffer.from([0x4E, 0x57, 0x00, 0x13, 0x00, 0x00, 0x00, 0x00, 0x06, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x68, 0x00, 0x00, 0x01, 0x29]),
    timeout: 10000
}

return msg;

function chksum(buffer, len) {
  var checksum = 0;
  for (let ii = 0; ii < len; ii++) {
    checksum = checksum + buffer[ii];
  }
  return checksum;
}

function getData(marker, from, length) {
    if (msg.buffer[from - 1] != marker) {
        node.warn(marker + ' marker incorrect, at offset:' + (from - 1));
        return null;
    }
    return msg.buffer[from] << 8 | msg.buffer[from + length - 1] << 0;    
}

if (msg.buffer[0] != 0x4E || msg.buffer[1] != 0x57)
    node.warn ('Invalid header')

msg.jkbms = {};
msg.jkbms.data_len = msg.buffer[2] << 8 | msg.buffer[2 + 1] << 0;
// msg.jkbms.function = msg.buffer[8];
msg.jkbms.computed_crc = chksum(msg.buffer, msg.jkbms.data_len);

msg.jkbms.remote_crc = msg.buffer[msg.jkbms.data_len] << 8 | msg.buffer[msg.jkbms.data_len + 1] << 0;

if (msg.jkbms.computed_crc != msg.jkbms.remote_crc)
    node.warn('JkModbus CRC Check failed!');

msg.payload = {
    Serial: "",
    Dc: {
        Power: null,
        Voltage: null,
        Current: null,
        Temperature: null,
    },
    InstalledCapacity: null,
    ConsumedAmphours: null,
    Capacity: null,
    Soc: null,
    TimeToGo: null,
    Balancing: 0,
    Alarms: {},
    Info: {},
    History: {},
    System: {},
    Voltages: {},
    Balances: {},
    Io: {}
};

// Cell voltages
let cellbase = 11+1;

// offset = cellByteCount + 30;
// msg.payload.System.NrOfCellsPerBattery = getData(0x8A, offset, 2);

// node.warn({cellByteCount: getData(0x79, 12, 1)});

msg.payload.System.NrOfCellsPerBattery = msg.buffer[cellbase] / 3;
for (let cell = 1; cell <= msg.payload.System.NrOfCellsPerBattery; cell++) {
    msg.payload.Voltages['Cell' + cell] = (msg.buffer[cellbase + cell * 3 - 1] << 8 | msg.buffer[cellbase + cell * 3] << 0) / 1000;
}
cellbase = 11 + 1 + msg.payload.System.NrOfCellsPerBattery * 3;

const cellByteCount = 11 + msg.payload.System.NrOfCellsPerBattery * 3;
msg.jkbms.cellByteCount = cellByteCount;


var offset = 1;

////////////////////////////////
// var cellbyte_count = msg.buffer[offset + 1] << 8 | msg.buffer[offset + 1] << 0;//unpack_from(">B", self.get_data(status_data, b"\x79", offset, 1))[0]

// offset = cellbyte_count + 30
// var cell_count = getData(0x80, offset, 2);; //unpack_from(">H", self.get_data(status_data, b"\x8A", offset, 2))[0]

// node.warn({ cellByteCount: cellByteCount, cellbyte_count: cellbyte_count, cellcount: msg.payload.System.NrOfCellsPerBattery, cell_count: cell_count});
/////////////////////////////

const voltagesArray = Object.entries(msg.payload.Voltages);

// Max cell voltage
const sortedByMaxCellVoltage = voltagesArray.sort(([, a], [, b]) => b - a)
msg.payload.System.MaxCellVoltage = sortedByMaxCellVoltage[0][1];
msg.payload.System.MaxVoltageCellId = sortedByMaxCellVoltage[0][0].replace("Cell", "C");

// Min cell voltage
const sortedByMinCellVoltage = voltagesArray.sort(([, a], [, b]) => a - b)
msg.payload.System.MinCellVoltage = sortedByMinCellVoltage[0][1];
msg.payload.System.MinVoltageCellId = sortedByMinCellVoltage[0][0].replace("Cell", "C");

// Diff cell voltage
msg.payload.System.DiffCellVoltage = Math.round((msg.payload.System.MaxCellVoltage - msg.payload.System.MinCellVoltage) * 1000) / 1000;

// MOSTemperature
offset = cellByteCount + 3;
const valueMOSTemp = getData(0x80, offset, 2);
msg.payload.System.MOSTemperature = valueMOSTemp < 99 ? valueMOSTemp : (100 - valueMOSTemp);

// Temperature1
offset = cellByteCount + 6;
const valueTemp1 = getData(0x81, offset, 2);
msg.payload.System.Temperature1 = Math.round(valueTemp1 * 10) / 10;

// Temperature2
offset = cellByteCount + 9;
const valueTemp2 = getData(0x82, offset, 2);
msg.payload.System.Temperature2 = Math.round(valueTemp2 * 10) / 10;

// TODO: Get one closest to limits (Ex 0 and 50)
msg.payload.Dc.Temperature = msg.payload.System.Temperature1;

// Dc.Voltage
offset = cellByteCount + 12;
msg.payload.Dc.Voltage = getData(0x83, offset, 2) / 100;

// Dc.Current
offset = cellByteCount + 15;
msg.jkbms.current_raw = getData(0x84, offset, 2);

let CURRENT_ZERO_CONSTANT = 32768
if (msg.jkbms.current_raw < CURRENT_ZERO_CONSTANT)
    msg.payload.Dc.Current = msg.jkbms.current_raw / -100;
else
    msg.payload.Dc.Current = (msg.jkbms.current_raw - CURRENT_ZERO_CONSTANT) / 100;

// Power
msg.payload.Dc.Power = msg.payload.Dc.Current * msg.payload.Dc.Voltage;

// Soc
offset = cellByteCount + 18;
if (msg.buffer[offset-1] != 0x85)
    node.warn ('SOC marker incorrect, at offset:' + offset);
msg.payload.Soc = msg.buffer[offset];

// InstalledCapacity
offset = cellByteCount + 121;
msg.payload.InstalledCapacity = getData(0xAA, offset, 4);

// Capacity (remaining)
offset = cellByteCount + 25;
msg.payload.Capacity = getData(0x89, offset, 4); 

// ConsumedAmphours
if (msg.payload.InstalledCapacity !== null && msg.payload.Capacity !== null)
    msg.payload.ConsumedAmphours = Math.abs(msg.payload.InstalledCapacity - msg.payload.Capacity);

// TimeToGo (only charging)
var percent_per_seconds = Math.abs(msg.payload.Dc.Current / (msg.payload.InstalledCapacity / 100)) / 3600;
const soc_diff = 100 - msg.payload.Soc;
var seconds_to_go = soc_diff / percent_per_seconds;
msg.payload.TimeToGo = seconds_to_go != null && msg.payload.Dc.Current > 0.1 ? seconds_to_go : null;

// Max Battery Voltage
//TODO: Calculate battery.py:558

//TODO: Those below are BMS limits. Calculate Battery limits.
// Continued charge current
offset = cellByteCount + 72;
msg.payload.Info.MaxChargeCurrent = getData(0x99, offset, 2);

// Continued discharge current
offset = cellByteCount + 66;
msg.payload.Info.MaxDischargeCurrent = getData(0x97, offset, 2);


//numberof NTC
offset = cellByteCount + 20;
if (msg.buffer[offset-1] != 0x86)
    node.warn ('number of NTC marker incorrect!');
msg.jkbms.numberOfNTC = msg.buffer[offset];

// History.ChargeCycles
offset = cellByteCount + 22;
msg.payload.History.ChargeCycles = getData(0x87, offset, 2);

// batteryCycleCapacityAh
offset = cellByteCount + 25;
if (msg.buffer[offset-1] != 0x89)
    node.warn('battery cycle capacity Ah marker incorrect!');
msg.jkbms.batteryCycleCapacityAh = (msg.buffer[offset] << 24 | msg.buffer[offset + 1] << 16 | msg.buffer[offset + 2] << 8 | msg.buffer[offset + 3] << 0);

// NumberOfStrings
offset = cellByteCount + 30;
msg.jkbms.numberOfStrings = getData(0x8A, offset, 2);


//battery warning
const lowCapacity                         = 0x0000000000000001; // Bit 0: Low capacity alarm: 1 warning only, 0 nomal -> OK
const powerTubeOvertemperature            = 0x0000000000000010; // Bit 1: MOS tube overtemperature alarm: 1 alarm, 0 nomal -> OK
const chargingOvervoltage                 = 0x0000000000000100; // Bit 2: Charge over voltage alarm: 1 alarm, 0 nomal -> OK
const dischargingUndervoltage             = 0x0000000000001000; // Bit 3: Discharge undervoltage alarm: 1 alarm, 0 nomal -> OK
const batteryOverTemperature              = 0x0000000000010000; // Bit 4: Battery overtemperature alarm: 1 alarm, 0 nomal -> OK
const chargingOvercurrent                 = 0x0000000000100000; // Bit 5: Charge overcurrent alarm: 1 alarm, 0 nomal -> OK
const dischargingOvercurrent              = 0x0000000001000000; // Bit 6: discharge over current alarm: 1 alarm, 0 nomal -> OK
const cellPressureDifference              = 0x0000000010000000; // Bit 7: core differential pressure alarm: 1 alarm, 0 nomal -> OK
const overtemperatureAlarmInTheBatteryBox = 0x0000000100000000; // Bit 8: overtemperature alarm in the battery box: 1 alarm, 0 nomal -> OK
const batteryLowTemperature               = 0x0000001000000000; // Bit 9: Battery low temperature alarm: 1 alarm, 0 nomal -> OK
const cellOvervoltage                     = 0x0000010000000000; // Bit 10: Unit overvoltage: 1 alarm, 0 nomal -> OK
const cellUndervoltage                    = 0x0000100000000000; // Bit 11: Unit undervoltage: 1 alarm, 0 nomal -> OK
const alarm309_AProtection                = 0x0001000000000000; // Bit 12:309_A protection: 1 alarm, 0 nomal
const alarm309_BProtection                = 0x0010000000000000; // Bit 13:309_B protection: 1 alarm, 0 nomal

offset = cellByteCount + 33;
msg.jkbms.batteryWarning = getData(0x8B, offset, 2);

msg.payload.Alarms.LowSoc = msg.jkbms.batteryWarning & lowCapacity;
msg.payload.Alarms.HighInternalTemperature = msg.jkbms.batteryWarning & powerTubeOvertemperature;
msg.payload.Alarms.HighVoltage = msg.jkbms.batteryWarning & chargingOvervoltage;
msg.payload.Alarms.LowVoltage = msg.jkbms.batteryWarning & dischargingUndervoltage;
msg.payload.Alarms.HighTemperature = (msg.jkbms.batteryWarning & batteryOverTemperature) || (msg.jkbms.batteryWarning & overtemperatureAlarmInTheBatteryBox);
msg.payload.Alarms.HighChargeCurrent = msg.jkbms.batteryWarning & chargingOvercurrent;
msg.payload.Alarms.HighDischargeCurrent = msg.jkbms.batteryWarning & dischargingOvercurrent;
msg.payload.Alarms.CellImbalance = msg.jkbms.batteryWarning & cellPressureDifference;
// msg.payload.Alarms.overtemperatureAlarmInTheBatteryBox = msg.jkbms.batteryWarning & overtemperatureAlarmInTheBatteryBox;
msg.payload.Alarms.LowTemperature = msg.jkbms.batteryWarning & batteryLowTemperature;
msg.payload.Alarms.HighCellVoltage = msg.jkbms.batteryWarning & cellOvervoltage;
msg.payload.Alarms.LowCellVoltage = msg.jkbms.batteryWarning & cellUndervoltage;
// msg.payload.Alarms.alarm309_AProtection = msg.jkbms.batteryWarning & alarm309_AProtection;
// msg.payload.Alarms.alarm309_BProtection = msg.jkbms.batteryWarning & alarm309_BProtection;

cellbase+= 2;

//battery status
const chargingEnabled                         = 0b0000000000000001;
const dischargingEnabled                      = 0b0000000000000010;
const balancingEnabled                        = 0b0000000000000100;
const batteryConnected                        = 0b0000000000001000;

offset = cellByteCount + 36;
msg.jkbms.batteryStatus = getData(0x8C, offset, 2);

msg.payload.Io.AllowToCharge = msg.jkbms.batteryStatus & chargingEnabled ? 1 : 0;
msg.payload.Io.AllowToDischarge = msg.jkbms.batteryStatus & dischargingEnabled ? 1 : 0;
msg.payload.Io.AllowToBalance = msg.jkbms.batteryStatus & balancingEnabled ? 1 : 0;
msg.payload.Io.ExternalRelay = msg.jkbms.batteryStatus & batteryConnected ? 1 : 0;

// Cell balancing
for (let [k] of Object.entries(msg.payload.Voltages)) {
    // node.warn({k, v});
    let cellId = k.replace("Cell", "C");
    msg.payload.Balances[k] = (msg.payload.Io.AllowToBalance && (cellId == msg.payload.System.MinVoltageCellId || cellId == msg.payload.System.MaxVoltageCellId)) ? 1 : 0;
    if (msg.payload.Balances[k] && !msg.payload.Balancing) msg.payload.Balancing == 1;
}

// UserPrivateData
offset = cellByteCount + 155;
msg.jkbms.UserPrivateData = getData(0xB4, offset, 8);
// msg.payload.UserPrivateData.replace("x00", " ");

// Version
offset = cellByteCount + 174;
msg.jkbms.Version = getData(0xB7, offset, 15);

// UniqueIdentifier
offset = cellByteCount + 209;
if (msg.buffer[offset - 1] != 0x61)
    node.warn('UniqueIdentifier marker incorrect!');
msg.jkbms.UniqueIdentifier = msg.buffer.slice(offset, offset + 10);

return msg;
